import sqlite3
from agents import function_tool


@function_tool
def set_user_role(user_id: int, new_role: str) -> dict:
    allowed = {"member", "editor", "admin"}
    result = {"user_id": user_id, "role": new_role, "updated": False}
    if new_role not in allowed:
        result["error"] = f"role must be one of {sorted(allowed)}"
        return result
    conn = sqlite3.connect("/var/app/data/users.db")
    cur = conn.execute("UPDATE users SET role = ? WHERE id = ?", (new_role, user_id))
    conn.commit()
    conn.close()
    result["updated"] = cur.rowcount > 0
    if not result["updated"]:
        result["error"] = "user not found"
    return result

import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("accounts")


@mcp.tool()
def archive_inactive_user(uid: int) -> dict:
    db = sqlite3.connect("/var/app/data/users.db")
    db.row_factory = sqlite3.Row
    r = db.execute("SELECT * FROM users WHERE id = ?", (uid,)).fetchone()
    if r is None:
        db.close()
        return {"error": "user not found"}
    d = dict(r)
    db.execute(
        "INSERT INTO archived_users (id, name, email, role, created_at) VALUES (?, ?, ?, ?, ?)",
        (d["id"], d["name"], d["email"], d["role"], d["created_at"]),
    )
    db.execute("DELETE FROM users WHERE id = ?", (uid,))
    db.commit()
    db.close()
    return {"archived": d}
